unit_tests:
db = UserData()
user_id = db.add_user("Charlie", "charlie@example.com", 35)
assert db.get_user(user_id) == {'name': 'Charlie', 'email': 'charlie@example.com', 'age': 35}

try:
    factorial(-1)
except ValueError as e:
    assert str(e) == "Factorial is not defined for negative numbers"

try:
    factorial(-5)
except ValueError as e:
    assert str(e) == "Factorial is not defined for negative numbers"

try:
    factorial(-10)
except ValueError as e:
    assert str(e) == "Factorial is not defined for negative numbers"

emp = Employee("John Doe", 12345, "Engineering", 70000, "2020-08-15")
try:
    emp.give_raise(-5)
except ValueError as e:
    assert str(e) == "Percentage raise must be non-negative"
